from pybricks.parameters import Stop
from pybricks.tools import wait

def phoenix_gyro_turn(fast_speed, fast_end_angle, slow_speed, final_end_angle, direction, phoenix_drive_base):
    phoenix_drive_base.use_gyro(True)
    phoenix_drive_base.reset(0, 0)
    if 'right' in direction:
        while not phoenix_drive_base.angle() >= fast_end_angle:
            phoenix_drive_base.drive(0, fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() >= final_end_angle:
            phoenix_drive_base.drive(0, slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()
    else:
        while not phoenix_drive_base.angle() <= fast_end_angle:
            phoenix_drive_base.drive(0, fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() <= final_end_angle:
            phoenix_drive_base.drive(0, slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()

def phoenix_gyro_spin_turn_with_deceleration(fast_speed, fast_end_angle, deceleration_steps, final_end_angle, direction, phoenix_drive_base, left_drive_motor, right_drive_motor):
    phoenix_drive_base.use_gyro(True)
    phoenix_drive_base.reset(0, 0)
    if 'right' in direction:
        while not phoenix_drive_base.angle() >= fast_end_angle:
            left_drive_motor.run(fast_speed)
            right_drive_motor.run(0 - fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() >= final_end_angle:
            left_drive_motor.run(slow_speed)
            right_drive_motor.run(0 - slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()
    else:
        while not phoenix_drive_base.angle() <= fast_end_angle:
            right_drive_motor.run(fast_speed)
            left_drive_motor.run(0 - fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() <= final_end_angle:
            right_drive_motor.run(slow_speed)
            left_drive_motor.run(0 - slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()

def phoenix_gyro_spin_turn_the_old_way(fast_speed, fast_end_angle, slow_speed, final_end_angle, direction, phoenix_drive_base, left_drive_motor, right_drive_motor):
    phoenix_drive_base.use_gyro(True)
    phoenix_drive_base.reset(0, 0)
    if 'right' in direction:
        while not phoenix_drive_base.angle() >= fast_end_angle:
            left_drive_motor.run(fast_speed)
            right_drive_motor.run(0 - fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() >= final_end_angle:
            left_drive_motor.run(slow_speed)
            right_drive_motor.run(0 - slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()
    else:
        while not phoenix_drive_base.angle() <= fast_end_angle:
            right_drive_motor.run(fast_speed)
            left_drive_motor.run(0 - fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() <= final_end_angle:
            right_drive_motor.run(slow_speed)
            left_drive_motor.run(0 - slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()


